int parse_record(const uint8_t *buf, size_t len) {
    if (len < 8) return -1;
    uint32_t stored = read_u32(buf + len - 4);
    if (crc32(buf, len - 4) != stored) {
        return -1;
    }
    return parse_fields(buf, len - 4);
}

