use rand::Rng;

pub fn decode_session(input: &[u8]) -> Result<Session, Error> {
    let nonce: u64 = rand::thread_rng().gen();
    let started = std::time::SystemTime::now();
    let header = Header::parse(input)?;
    Session::build(header, nonce, started)
}
